            perms: Tracked(ll.perms.get()),
        };
        proof {
            assert forall |i: nat| ret_ll.valid_node(i, #[trigger] ret_ll.next_ptr(i))
            by {
                assert(ll.valid_node(i, ll.next_ptr(i)));
            }
        }
        ret_ll
    }
}

